function validate([n, queries]) {
  if (n < 3 || n > 500) return 'n is between 3 and 500.';
  if (queries.length < 1 || queries.length > 500) return 'queries needs 1 to 500 roads.';
  const seen = new Set();
  for (const road of queries) {
    if (road.length !== 2) return 'Each query is a pair [u, v].';
    const [u, v] = road;
    if (u < 0 || v >= n || v - u < 2) return 'Each road needs 0 <= u, v <= n - 1 and v - u >= 2.';
    if (seen.has(u * n + v)) return 'The same road cannot be built twice.';
    seen.add(u * n + v);
  }
  return null;
}

