function shortestDistanceAfterQueries(n, queries) {
  const roads = Array.from({ length: n }, (_, city) => (city + 1 < n ? [city + 1] : []));
  const answer = [];
  for (const [u, v] of queries) {
    roads[u].push(v);
    const dist = new Array(n).fill(-1);
    dist[0] = 0;
    const queue = [0];
    for (let head = 0; head < queue.length; head++) {
      const city = queue[head];
      for (const neighbor of roads[city]) {
        if (dist[neighbor] === -1) {
          dist[neighbor] = dist[city] + 1;
          queue.push(neighbor);
        }
      }
    }
    answer.push(dist[n - 1]);
  }
  return answer;
}

