function shortestDistanceAfterQueries(n, queries) {
  // Every road leads to a larger city, so each city's distance follows from the roads coming into it,
  // filled in increasing city order.
  const incoming = Array.from({ length: n }, (_, city) => (city > 0 ? [city - 1] : []));
  const answer = [];
  for (const [u, v] of queries) {
    incoming[v].push(u);
    const best = [0];
    for (let city = 1; city < n; city++) {
      best[city] = Math.min(...incoming[city].map(from => best[from] + 1));
    }
    answer.push(best[n - 1]);
  }
  return answer;
}

