function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(400, 500) : int(3, 9);
  // Short roads make the distance shrink slowly; long ones can jump close to the last city at once.
  const longest = large && rand() < 0.5 ? int(2, 6) : n - 1;
  let available = 0;
  for (let span = 2; span <= longest; span++) available += n - span;
  const count = Math.min(available, large ? int(400, 500) : int(1, 8));
  const used = new Set();
  const queries = [];
  while (queries.length < count) {
    const u = int(0, n - 3);
    const v = int(u + 2, Math.min(n - 1, u + longest));
    if (used.has(u * n + v)) continue;
    used.add(u * n + v);
    queries.push([u, v]);
  }
  return [n, queries];
}
